import{u as r,C as o,o as t,c as i,j as a,a as s,k as h,E as d,e as c,al as p}from"./chunks/framework.7vp1BMOE.js";const g={key:0},f=JSON.parse('{"title":"Release Process","description":"","frontmatter":{},"headers":[],"relativePath":"zh/releases/release_process.md","filePath":"zh/releases/release_process.md"}'),u={name:"zh/releases/release_process.md"},F=Object.assign(u,{setup(k){const{site:l}=r();return(b,e)=>{const n=o("Redirect");return t(),i("div",null,[e[1]||(e[1]=a("h1",{id:"release-process",tabindex:"-1"},[s("Release Process "),a("a",{class:"header-anchor",href:"#release-process","aria-label":'Permalink to "Release Process"'},"​")],-1)),h(l).title!=="PX4 Guide (main)"?(t(),i("div",g,[e[0]||(e[0]=a("div",{class:"custom-block danger"},[a("p",{class:"custom-block-title"},[s("This page is on a release branch, and hence probably out of date. "),a("a",{href:"https://docs.px4.io/main/en/releases/release_process"},"See the latest version"),s(".")])],-1)),d(n,{to:"https://docs.px4.io/main/en/releases/release_process"})])):c("",!0),e[2]||(e[2]=p(`<p>This page documents the PX4 release process for maintainers. It covers the steps from preparing a release candidate through to the final announcement.</p><h2 id="综述" tabindex="-1">综述 <a class="header-anchor" href="#综述" aria-label="Permalink to &quot;综述&quot;">​</a></h2><p>PX4 uses a branch-based release workflow:</p><ul><li><strong><code>release/X.Y</code></strong> (e.g., <code>release/1.17</code>, <code>release/2.0</code>) - The active development branch for a specific release where changes are merged and tested</li><li><strong><code>stable</code></strong> - Points to the latest stable release tag; reset after each release</li><li><strong><code>beta</code></strong> - For flight testers to validate release candidates</li></ul><p>The target release cycle is approximately 6 months, best effort. The actual cadence depends on testing results and maintainer availability, with an ongoing goal to shorten the cycle.</p><p>Releases are tracked on the <a href="https://github.com/orgs/PX4/projects/45" target="_blank" rel="noreferrer">PX4 Release Project Board</a>, which is reused and renamed for each release cycle.</p><h3 id="release-tag-progression" tabindex="-1">Release Tag Progression <a class="header-anchor" href="#release-tag-progression" aria-label="Permalink to &quot;Release Tag Progression&quot;">​</a></h3><p>Release branches go through the following tag stages:</p><table tabindex="0"><thead><tr><th>Stage</th><th>Example</th><th>Branch Status</th><th>What Gets Merged</th></tr></thead><tbody><tr><td><strong>Alpha</strong></td><td><code>v1.18.0-alpha1</code></td><td>Open for fixes</td><td>Bug fixes and regression fixes only</td></tr><tr><td><strong>Beta</strong></td><td><code>v1.18.0-beta1</code></td><td>Open for fixes</td><td>Bug fixes and regression fixes only</td></tr><tr><td><strong>RC</strong></td><td><code>v1.18.0-rc1</code></td><td>Frozen</td><td>Nothing (unless veto vote passes)</td></tr><tr><td><strong>Stable</strong></td><td><code>v1.18.0</code></td><td>Open for fixes</td><td>Bug fixes and regression fixes (for point releases)</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>New features are never merged to release branches. Once a release branch is created from <code>main</code>, only bug fixes and regression fixes are accepted. New features must target <code>main</code> and will be included in the next release cycle.</p></div><h2 id="starting-a-new-release-cycle" tabindex="-1">Starting a New Release Cycle <a class="header-anchor" href="#starting-a-new-release-cycle" aria-label="Permalink to &quot;Starting a New Release Cycle&quot;">​</a></h2><p>A new release cycle begins immediately after a stable release is published. This involves two votes during the <a href="./../contribute/dev_call">Weekly Community Q&amp;A Call</a> when approving a stable release:</p><ol><li><strong>Vote to publish the current release</strong> - Approve the stable release for publication</li><li><strong>Vote on the next release name/number</strong> - Decide the version number for the next release (e.g., v1.18 or v2.0)</li></ol><h3 id="prepare-release-notes-before-branching" tabindex="-1">Prepare Release Notes Before Branching <a class="header-anchor" href="#prepare-release-notes-before-branching" aria-label="Permalink to &quot;Prepare Release Notes Before Branching&quot;">​</a></h3><p>Release notes are built incrementally in <a href="./../releases/main"><code>main.md</code></a>, which accumulates changes as they land on <code>main</code>. Before creating the release branch:</p><ol><li><p>Rename <code>main.md</code> to the version-specific file (e.g., <code>docs/en/releases/1.18.md</code>)</p></li><li><p>Add the new file to <code>SUMMARY.md</code> and <code>releases/index.md</code></p></li><li><p>Reset <code>main.md</code> to a clean template for the next release cycle</p></li><li><p>Verify that documentation for all included contributions is complete</p></li><li><p>Search for instances of <code>main (planned for:</code> and replace with the release version now that it is known. So, for example <code>&lt;Badge type=&quot;tip&quot; text=&quot;main (planned for PX4 v1.xx&quot; /&gt;</code> is replaced with <code>&lt;Badge type=&quot;tip&quot; text=&quot;PX4 v1.xx&quot; /&gt;</code>.</p><p>Note that once the name of the next version is confirmed, badges may use the second form (e.g. <code>&lt;Badge type=&quot;tip&quot; text=&quot;PX4 v1.18&quot; /&gt;</code>.</p></li><li><p>Search for instances of <code>&lt;Badge type=&quot;warning&quot; text=&quot;Experimental&quot; /&gt;</code>. Remove this for features that are considered core and/or stable.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Community members are encouraged to document changes as they are merged into <code>main</code>. This distributes the documentation workload and ensures changes are captured while they&#39;re fresh.</p></div><h3 id="create-the-release-branch" tabindex="-1">Create the Release Branch <a class="header-anchor" href="#create-the-release-branch" aria-label="Permalink to &quot;Create the Release Branch&quot;">​</a></h3><p>Once the next release version is decided, create the new release branch from <code>main</code> in PX4-Autopilot and the companion repositories:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># PX4-Autopilot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release/1.18</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release/1.18</span></span></code></pre></div><p>Matching release branches must also be created in:</p><ul><li><a href="https://github.com/PX4/px4_msgs" target="_blank" rel="noreferrer">PX4/px4_msgs</a></li><li><a href="https://github.com/Auterion/px4-ros2-interface-lib" target="_blank" rel="noreferrer">Auterion/px4-ros2-interface-lib</a></li></ul><p>After creating the companion branches, update the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/.github/workflows/ros_integration_tests.yml" target="_blank" rel="noreferrer">ROS integration test workflow</a> on the release branch to clone <code>px4-ros2-interface-lib</code> from the matching release branch:</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">- git clone --recursive https://github.com/Auterion/px4-ros2-interface-lib.git</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+ git clone --recursive --branch release/1.18 https://github.com/Auterion/px4-ros2-interface-lib.git</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Once the release branches are created, they only accept bug fixes and regression fixes. All new feature development continues on <code>main</code>.</p></div><h3 id="create-the-alpha-tag" tabindex="-1">Create the Alpha Tag <a class="header-anchor" href="#create-the-alpha-tag" aria-label="Permalink to &quot;Create the Alpha Tag&quot;">​</a></h3><p>Immediately after creating the release branch, create the first alpha tag to mark the beginning of the release cycle:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On the new release branch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release/1.18</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create the signed alpha tag</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.18.0-alpha1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;v1.18.0-alpha1&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.18.0-alpha1</span></span></code></pre></div><p>Subsequent alpha tags can be created as fixes are merged (e.g., <code>v1.18.0-alpha2</code>, <code>v1.18.0-alpha3</code>).</p><h2 id="release-steps" tabindex="-1">Release Steps <a class="header-anchor" href="#release-steps" aria-label="Permalink to &quot;Release Steps&quot;">​</a></h2><h3 id="_1-review-and-merge-prs-alpha-phase" tabindex="-1">1. Review and Merge PRs (Alpha Phase) <a class="header-anchor" href="#_1-review-and-merge-prs-alpha-phase" aria-label="Permalink to &quot;1. Review and Merge PRs (Alpha Phase)&quot;">​</a></h3><p>During the alpha phase, review pull requests targeting the release branch:</p><ul><li>Review PRs according to the project&#39;s <a href="./../contribute/code">contribution guidelines</a></li><li>Merge <strong>bug fixes and regression fixes only</strong></li><li>New features must target <code>main</code>, not the release branch</li><li>Create additional alpha tags as fixes are merged (e.g., <code>v1.18.0-alpha2</code>)</li></ul><h3 id="_2-alpha-testing" tabindex="-1">2. Alpha Testing <a class="header-anchor" href="#_2-alpha-testing" aria-label="Permalink to &quot;2. Alpha Testing&quot;">​</a></h3><p>The <em>Dronecode Test Team</em> (provided by <a href="https://www.ascendengineer.com" target="_blank" rel="noreferrer">Ascend Engineering</a> — Dronecode Silver member) conducts initial flight testing of alpha builds using:</p><ul><li>The <a href="./../test_and_ci/test_flights">test cards</a> documented in the PX4 guide</li><li>A hardware matrix covering supported flight controllers and airframes</li></ul><p>Alpha testing focuses on identifying regressions and blockers early. The alpha phase is complete when:</p><ul><li>All test cards pass across the core hardware matrix (no critical or high-severity failures)</li><li>All identified regressions have fixes merged or have been triaged as non-blocking</li><li>Release notes and documentation for included changes are complete</li></ul><h3 id="_3-create-beta-tag" tabindex="-1">3. Create Beta Tag <a class="header-anchor" href="#_3-create-beta-tag" aria-label="Permalink to &quot;3. Create Beta Tag&quot;">​</a></h3><p>Once the alpha exit criteria above are met, create the first beta tag:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On the release branch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release/1.18</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create the signed beta tag</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.18.0-beta1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;v1.18.0-beta1&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.18.0-beta1</span></span></code></pre></div><h3 id="_4-beta-testing" tabindex="-1">4. Beta Testing <a class="header-anchor" href="#_4-beta-testing" aria-label="Permalink to &quot;4. Beta Testing&quot;">​</a></h3><p>Beta builds are published for wider community validation. Unlike alpha testing (which is conducted by the Dronecode Test Team on the core hardware matrix), beta testing focuses on:</p><ul><li><strong>Community testing</strong> — beta builds are made available for community members to test on their own hardware and airframe configurations</li><li><strong>Extended hardware coverage</strong> — testing on hardware and configurations beyond the core test matrix</li><li><strong>Real-world flight scenarios</strong> — longer flights, mission testing, and edge cases not covered by standard test cards</li></ul><p>During beta, continue to:</p><ul><li>Review and merge <strong>bug fixes and regression fixes only</strong></li><li>Create additional beta tags as fixes are merged (e.g., <code>v1.18.0-beta2</code>, <code>v1.18.0-beta3</code>)</li></ul><h3 id="_5-create-release-candidate-tag" tabindex="-1">5. Create Release Candidate Tag <a class="header-anchor" href="#_5-create-release-candidate-tag" aria-label="Permalink to &quot;5. Create Release Candidate Tag&quot;">​</a></h3><p>The beta phase is complete when:</p><ul><li>No new critical or high-severity issues are reported for at least one beta tag cycle</li><li>All beta-reported regressions have fixes merged or have been triaged as non-blocking</li></ul><p>Once the beta exit criteria are met, create the first release candidate:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On the release branch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release/1.18</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create the signed RC tag</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.18.0-rc1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;v1.18.0-rc1&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.18.0-rc1</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The branch is now frozen. No PRs will be merged unless a veto vote passes (see below).</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Tags must be GPG-signed. Ensure your GitHub account is <a href="https://docs.github.com/en/authentication/managing-commit-signature-verification" target="_blank" rel="noreferrer">configured for GPG signing</a>. Only maintainers with registered GPG keys can create release tags.</p></div><h3 id="_6-rc-testing-and-branch-freeze" tabindex="-1">6. RC Testing and Branch Freeze <a class="header-anchor" href="#_6-rc-testing-and-branch-freeze" aria-label="Permalink to &quot;6. RC Testing and Branch Freeze&quot;">​</a></h3><p>During RC testing, the release branch is frozen:</p><ul><li>No PRs are merged by default</li><li>Testing focuses on final validation before stable release</li><li>Any issues found are documented and evaluated</li></ul><h4 id="veto-vote-for-critical-fixes" tabindex="-1">Veto Vote for Critical Fixes <a class="header-anchor" href="#veto-vote-for-critical-fixes" aria-label="Permalink to &quot;Veto Vote for Critical Fixes&quot;">​</a></h4><p>If a critical issue is discovered during RC testing that must be fixed before release:</p><ol><li>Raise the issue during the <a href="./../contribute/dev_call">Weekly Community Q&amp;A Call</a></li><li>Present the case for why the fix is critical</li><li>Maintainers vote on whether to merge the fix</li><li>If approved, merge the fix and create a new RC tag (e.g., <code>v1.18.0-rc2</code>)</li></ol><h3 id="_7-release-vote" tabindex="-1">7) Release Vote <a class="header-anchor" href="#_7-release-vote" aria-label="Permalink to &quot;7) Release Vote&quot;">​</a></h3><p>The release vote takes place during the <a href="./../contribute/dev_call">Weekly Community Q&amp;A Call</a>:</p><ul><li>Present the release status and test results</li><li><strong>Vote 1:</strong> Core maintainers vote on whether to publish the release</li><li><strong>Vote 2:</strong> Decide the name/number of the next release version</li><li>The call happens Wednesdays at 17:00 CET on <a href="https://discord.com/invite/BDYmr6FA6Q" target="_blank" rel="noreferrer">Discord</a></li></ul><h3 id="_8-create-and-push-release-tag" tabindex="-1">8. Create and Push Release Tag <a class="header-anchor" href="#_8-create-and-push-release-tag" aria-label="Permalink to &quot;8. Create and Push Release Tag&quot;">​</a></h3><p>After a successful vote, create the final release tag:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On the release branch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release/1.18</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create the signed release tag</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.18.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;v1.18.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.18.0</span></span></code></pre></div><h3 id="_9-update-the-stable-branch" tabindex="-1">9. Update the Stable Branch <a class="header-anchor" href="#_9-update-the-stable-branch" aria-label="Permalink to &quot;9. Update the Stable Branch&quot;">​</a></h3><p>Reset the <code>stable</code> branch to point to the new release tag:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.18.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is a force push that rewrites the stable branch history. Ensure you have the correct tag before executing.</p></div><h3 id="_10-github-release-automated" tabindex="-1">10. GitHub Release (Automated) <a class="header-anchor" href="#_10-github-release-automated" aria-label="Permalink to &quot;10. GitHub Release (Automated)&quot;">​</a></h3><p>When a version tag is pushed, the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/.github/workflows/build_all_targets.yml" target="_blank" rel="noreferrer">build_all_targets.yml</a> GitHub Actions workflow automatically:</p><ol><li>Builds firmware for all supported targets</li><li>Uploads firmware artifacts to AWS S3 (<code>Firmware/vX.Y.Z/</code> and updates <code>Firmware/stable/</code>)</li><li>Creates a <strong>draft release</strong> on GitHub with all <code>.px4</code> firmware files attached</li></ol><h3 id="_11-publish-github-release" tabindex="-1">11) Publish GitHub Release <a class="header-anchor" href="#_11-publish-github-release" aria-label="Permalink to &quot;11) Publish GitHub Release&quot;">​</a></h3><p>Edit the draft release on GitHub:</p><ul><li>Add a brief description of major changes</li><li>Link to the full release notes in the documentation (e.g., <code>releases/1.18.md</code>)</li><li>Publish the release</li></ul><h3 id="_12-finalize-documentation" tabindex="-1">12. Finalize Documentation <a class="header-anchor" href="#_12-finalize-documentation" aria-label="Permalink to &quot;12. Finalize Documentation&quot;">​</a></h3><p>Review and finalize the release notes that have been developed throughout the release cycle:</p><ul><li>Ensure all noteworthy changes, new features, and upgrade guides are documented</li><li>Review for completeness and accuracy</li><li>See existing <a href="./../releases/">release notes</a> for the expected format</li></ul><h3 id="_13-announce-the-release" tabindex="-1">13. Announce the Release <a class="header-anchor" href="#_13-announce-the-release" aria-label="Permalink to &quot;13. Announce the Release&quot;">​</a></h3><p>Announce the release through official channels:</p><ul><li><a href="https://discuss.px4.io/" target="_blank" rel="noreferrer">PX4 Discuss Forum</a></li><li><a href="https://discord.com/invite/dronecode" target="_blank" rel="noreferrer">PX4 Discord</a></li><li>Social media (Twitter/X, LinkedIn)</li><li>Dronecode newsletter</li></ul><h3 id="_14-start-next-release-cycle" tabindex="-1">14. Start Next Release Cycle <a class="header-anchor" href="#_14-start-next-release-cycle" aria-label="Permalink to &quot;14. Start Next Release Cycle&quot;">​</a></h3><p>Immediately after publishing, start the next release cycle:</p><ul><li>Create the new release branch from <code>main</code> (see <a href="#create-the-release-branch">Create the Release Branch</a>)</li><li>Create the alpha tag for the new release</li><li>Create the initial documentation for the next release</li><li>Rename and prepare the project board (see <a href="#project-board-management">Project Board Management</a>)</li></ul><h2 id="point-releases" tabindex="-1">Point Releases <a class="header-anchor" href="#point-releases" aria-label="Permalink to &quot;Point Releases&quot;">​</a></h2><p>After a stable release is published, the release branch reopens for bug fixes and regression fixes to support point releases (e.g., <code>v1.18.1</code>).</p><p>For patch releases:</p><ol><li>Merge bug fixes and regression fixes to the release branch</li><li>Create beta tags for testing if needed (e.g., <code>v1.18.1-beta1</code>)</li><li>Create RC tags for final validation (e.g., <code>v1.18.1-rc1</code>)</li><li>After testing and vote, tag the point release</li><li>Update stable branch and publish</li></ol><h2 id="project-board-management" tabindex="-1">Project Board Management <a class="header-anchor" href="#project-board-management" aria-label="Permalink to &quot;Project Board Management&quot;">​</a></h2><p>The <a href="https://github.com/orgs/PX4/projects/45" target="_blank" rel="noreferrer">PX4 Release Project Board</a> is reused across release cycles to track issues and PRs for the current release.</p><h3 id="after-a-release" tabindex="-1">After a Release <a class="header-anchor" href="#after-a-release" aria-label="Permalink to &quot;After a Release&quot;">​</a></h3><p>Once a release is published:</p><ol><li><strong>Rename the project board</strong> to reflect the next release version (e.g., &quot;v1.17 Release&quot; → &quot;v1.18 Release&quot;)</li><li><strong>Review remaining items</strong>: <ul><li>Close items that are no longer relevant</li><li>Move incomplete items that should carry over to the next release</li><li>Remove items that were descoped or deferred indefinitely</li></ul></li><li><strong>Update the board description</strong> if needed to reflect the new release target</li></ol><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="./../contribute/code">Source Code Management</a> - Branching model and contribution guidelines</li><li><a href="./../test_and_ci/test_flights">Test Flights</a> - Flight test procedures and test cards</li><li><a href="./../contribute/dev_call">Weekly Community Q&amp;A Call</a> - Where release votes happen</li></ul>`,95))])}}});export{f as __pageData,F as default};
